# Debug step by step
expr = '5 1 2 + 4 * + 3 -'
print(f"Evaluating: {expr}")
stack = []
for tok in expr.split():
    print(f"Token: '{tok}', stack before: {stack}")
    if tok in ("+", "-", "*", "/"):
        b = stack.pop()
        a = stack.pop()
        result = apply_op(tok, a, b)
        print(f"  Operator '{tok}': a={a}, b={b}, result={result}")
        stack.append(result)
    else:
        val = float(tok)
        stack.append(val)
        print(f"  Value {val}, stack after push: {stack}")

print(f"Final result: {stack[0]}")
